/* ---------------- DoVibrato (src/pilot/DoVibrato.c) ---------------- */
/* Driver 2: DoVibrato */
void DoVibrato(void)
{
	unsigned char q;
	unsigned short temp = 0;
	q = (XMC->vibpos >> 2) & 0x1f;
	switch (XMC->wavecontrol & 3) {
	case 0: temp = D_0008D948[q]; break;
	case 1:
		q <<= 3;
		if (XMC->vibpos > 127) q = 255 - q;
		temp = q;
		break;
	case 2: temp = 255; break;
	}
	temp *= XMC->vibdepth;
	temp >>= 7;
	temp <<= 2;
	if (XMC->vibpos < 128)
		XMC->period = XMC->tmpperiod + temp;
	else
		XMC->period = XMC->tmpperiod - temp;
	if (D_00097814->vbtick) XMC->vibpos += XMC->vibspd;
}

/* ---------------- DoTremolo (src/pilot/DoTremolo.c) ---------------- */
/* Driver 2: DoTremolo */
void DoTremolo(void)
{
    unsigned char q;
    unsigned short temp = 0;
    q = (XMC->trmpos >> 2) & 0x1f;
    switch ((XMC->wavecontrol >> 4) & 3) {
    case 0: temp = D_0008D948[q]; break;
    case 1:
        q <<= 3;
        if (XMC->trmpos > 127) q = 255 - q;
        temp = q;
        break;
    case 2: temp = 255; break;
    }
    temp *= XMC->trmdepth;
    temp >>= 6;
    if (XMC->trmpos < 128) {
        XMC->volume = XMC->tmpvolume + temp;
        if (XMC->volume > 128) XMC->volume = 128;
    } else {
        XMC->volume = XMC->tmpvolume - temp;
        if (XMC->volume < 64) XMC->volume = 64;
    }
    if (D_00097814->vbtick) XMC->trmpos += XMC->trmspd;
}

